def normalize_key(name: str) -> str:
    """Normalize a docopt key to a Python-friendly identifier."""
    normalized = name.strip()
    if normalized.startswith("<") and normalized.endswith(">"):
        normalized = normalized[1:-1]
    normalized = normalized.lstrip("-").replace("-", "_").replace(" ", "_")
    return normalized


def convert_value(
    value: list[str] | str | bool | int | float | None,
    converter: Callable[[Any], Any] | type[Any] | None = None,
) -> Any:
    """Apply a converter to a parsed value while preserving docopt containers."""
    if converter is None or value is None:
        return value
    if isinstance(value, list):
        return [convert_value(item, converter) for item in value]
    if converter is bool:
        if isinstance(value, bool):
            return value
        lowered = str(value).strip().lower()
        if lowered in {"1", "true", "yes", "y", "on"}:
            return True
        if lowered in {"0", "false", "no", "n", "off", ""}:
            return False
        raise ValueError(f"Cannot coerce {value!r} to bool")
    return converter(value)


def convert_parsed_options(
    parsed: Mapping[str, Any],
    converters: Mapping[str, Callable[[Any], Any] | type[Any]],
    *,
    aliases: bool = True,
    strict: bool = False,
) -> "ParsedOptions":
    """Convert parsed docopt values using explicit per-key converters.

    Keys in `converters` may refer to exact docopt keys (`"--count"`) or to
    normalized aliases (`"count"`, `"input_file"`).
    """
    converted = ParsedOptions(parsed.items())
    alias_map = {normalize_key(key): key for key in parsed} if aliases else {}
    for key, converter in converters.items():
        target = key if key in converted else alias_map.get(key)
        if target is None:
            if strict:
                raise KeyError(key)
            continue
        converted[target] = convert_value(converted[target], converter)
    return converted


class ParsedOptions(dict[str, Any]):
    def __repr__(self) -> str:
        return "{%s}" % ",\n ".join("%r: %r" % i for i in sorted(self.items()))

    def __getattr__(self, name: str) -> str | bool | int | list[str] | None:
        return self.get(name) or {
            name: self.get(k)
            for k in self.keys()
            if name in [k.lstrip("-").replace("-", "_"), k.lstrip("<").rstrip(">")]
        }.get(name)

    def as_kwargs(self) -> dict[str, Any]:
        """Return the mapping with Python-friendly normalized keys."""
        return {normalize_key(key): value for key, value in self.items()}

    def convert(
        self,
        converters: Mapping[str, Callable[[Any], Any] | type[Any]],
        *,
        aliases: bool = True,
        strict: bool = False,
    ) -> "ParsedOptions":
        """Return a converted copy using `convert_parsed_options`."""
        return convert_parsed_options(self, converters, aliases=aliases, strict=strict)


def docopt(
